def E(a,ok,o=None):
    e=["틀리다."]*5; e[a-1]=ok
    for i,t in (o or {}).items(): e[i-1]=t
    return e
def M(a,ok,o=None):
    e=["맞다."]*5; e[a-1]=ok
    for i,t in (o or {}).items(): e[i-1]=t
